import { Pool } from "pg";
import {
  assessDay,
  assessTrip,
  disputeIsInWindow,
  istDate,
  PayoutAssessment,
  PayoutLine,
  TripRecord,
} from "../domain/payouts.js";
import { IssueUpdate } from "../infrastructure/llm/groq-client.js";

export type ClaimStatus = "needs_information" | "verified_shortfall" | "no_shortfall" | "unclear" | "suspicious";

export interface InvestigationTarget {
  issueId: string;
  update: IssueUpdate;
}

export interface InvestigationEvent {
  type: "tool_call" | "decision" | "error";
  name: string;
  input: unknown;
  output: unknown;
}

export interface ClaimOutcome {
  issue_id: string;
  status: ClaimStatus;
  scope: "trip" | "day" | null;
  reason: string;
  assessments: PayoutAssessment[];
  decision_path?: "needs_information" | "unclear_escalation" | "suspicious_escalation" | "large_claim_approval" | "repeat_claim_approval" | "repeat_already_paid_escalation" | "daily_limit_approval" | "payment_provider_unavailable" | "payment_guard_rejected" | "auto_payment_eligible" | "payment_succeeded" | "payment_result_uncertain" | "payment_failed_review" | "no_payment_due";
  decision_reason?: string;
  verified_owed_rupees?: number;
  decision_amount_rupees?: number | null;
  ops_item_id?: string | null;
  claim_fingerprint?: string;
  reply: string;
}

export interface InvestigationResult {
  outcomes: ClaimOutcome[];
  events: InvestigationEvent[];
}

interface DbTrip {
  trip_id: string;
  rider_id: string;
  started_at: Date;
  status: TripRecord["status"];
  distance_km: string;
  surge_multiplier: string;
}

interface DbPayoutLine {
  line_id: string;
  payout_date: string;
  rider_id: string;
  line_type: string;
  trip_id: string | null;
  amount_rupees: number;
}

function canonicalRiderId(value: string): string {
  const match = /^R(\d+)$/i.exec(value.trim());
  return match ? `R${Number(match[1]).toString().padStart(3, "0")}` : value.trim().toUpperCase();
}

function toTrip(row: DbTrip): TripRecord {
  return {
    tripId: row.trip_id,
    riderId: row.rider_id,
    startedAt: row.started_at,
    status: row.status,
    distanceKm: row.distance_km,
    surgeMultiplier: row.surge_multiplier,
  };
}

function toPayoutLine(row: DbPayoutLine): PayoutLine {
  return {
    lineId: row.line_id,
    payoutDate: row.payout_date,
    riderId: row.rider_id,
    lineType: row.line_type,
    tripId: row.trip_id,
    amountRupees: Number(row.amount_rupees),
  };
}

function resultStatus(shortfall: number): ClaimStatus {
  return shortfall > 0 ? "verified_shortfall" : "no_shortfall";
}

function resultReply(status: ClaimStatus, assessments: PayoutAssessment[], reason: string): string {
  if (status === "needs_information") {
    return reason === "date"
      ? "Could you share the trip ID or the date of the payout you want checked?"
      : "Could you share the trip ID related to the payout issue?";
  }
  if (status === "unclear") {
    return `I could not verify this claim from the available records: ${reason}. I have sent it to the operations team for review.`;
  }
  if (status === "suspicious") {
    return `The trip details do not match the rider account linked to this number. I have sent the case to the operations team to review.`;
  }

  const totalExpected = assessments.reduce((sum, item) => sum + item.expectedRupees, 0);
  const totalPaid = assessments.reduce((sum, item) => sum + item.historicalPaidRupees, 0);
  const shortfall = totalExpected - totalPaid;
  const dates = [...new Set(assessments.map((item) => item.payoutDate))];
  const dateLabel = dates.length === 1 ? dates[0] : dates.join(", ");
  if (status === "verified_shortfall") {
    return `I checked the ${assessments.length === 1 && assessments[0]!.scope === "trip" ? `trip ${assessments[0]!.tripId}` : "payout records"} for ${dateLabel}. Policy amount: ₹${totalExpected}; recorded payout: ₹${totalPaid}; verified shortfall: ₹${shortfall}. No payment was made in this step.`;
  }
  return `I checked the ${assessments.length === 1 && assessments[0]!.scope === "trip" ? `trip ${assessments[0]!.tripId}` : "payout records"} for ${dateLabel}. Policy amount: ₹${totalExpected}; recorded payout: ₹${totalPaid}. The records show no additional amount is due.`;
}

function outcome(
  issueId: string,
  status: ClaimStatus,
  scope: ClaimOutcome["scope"],
  reason: string,
  assessments: PayoutAssessment[] = [],
): ClaimOutcome {
  return {
    issue_id: issueId,
    status,
    scope,
    reason,
    assessments,
    reply: resultReply(status, assessments, reason),
  };
}

export async function investigateIssues(
  pool: Pool,
  riderId: string,
  receivedAt: Date,
  targets: InvestigationTarget[],
): Promise<InvestigationResult> {
  if (targets.length === 0) return { outcomes: [], events: [] };
  const events: InvestigationEvent[] = [];
  const lookupRiderId = canonicalRiderId(riderId);
  const rider = await pool.query<{ rider_id: string }>(
    "SELECT rider_id FROM riders WHERE rider_id = $1",
    [lookupRiderId],
  );
  events.push({
    type: "tool_call",
    name: "rider_record_lookup",
    input: { requested_rider_id: riderId, normalized_rider_id: lookupRiderId },
    output: { found: rider.rowCount === 1, rider_id: rider.rows[0]?.rider_id ?? null },
  });

  if (!rider.rows[0]) {
    const outcomes = targets.map(({ issueId }) => outcome(issueId, "unclear", null, "the rider account was not found"));
    for (const item of outcomes) events.push({ type: "decision", name: "claim_not_verifiable", input: { issue_id: item.issue_id }, output: item });
    return { outcomes, events };
  }

  const canonicalId = rider.rows[0].rider_id;
  const outcomes: ClaimOutcome[] = [];
  for (const target of targets) {
    const { issueId, update } = target;
    if (update.missing_information.includes("issue_details") && update.trip_ids.length === 0 && update.dates.length === 0) {
      outcomes.push(outcome(issueId, "needs_information", null, "issue_details"));
      continue;
    }

    if (update.trip_ids.length > 0) {
      const assessments: PayoutAssessment[] = [];
      let unclearReason: string | null = null;
      for (const tripId of [...new Set(update.trip_ids)]) {
        const tripResult = await pool.query<DbTrip>(
          `SELECT trip_id, rider_id, started_at, status,
                  distance_km::text AS distance_km, surge_multiplier::text AS surge_multiplier
           FROM trips WHERE trip_id = $1`,
          [tripId],
        );
        const row = tripResult.rows[0];
        events.push({
          type: "tool_call",
          name: "trip_record_lookup",
          input: { issue_id: issueId, trip_id: tripId },
          output: row ? { found: true, rider_id: row.rider_id, payout_date: istDate(row.started_at), status: row.status } : { found: false },
        });
        if (!row) {
          unclearReason = `trip ${tripId} was not found`;
          break;
        }
        if (row.rider_id !== canonicalId) {
          unclearReason = `trip ${tripId} is not linked to this rider account`;
          break;
        }
        const trip = toTrip(row);
        const tripDate = istDate(trip.startedAt);
        if (update.dates.length > 0 && !update.dates.includes(tripDate)) {
          unclearReason = `trip ${tripId} does not match the date provided`;
          break;
        }
        if (!disputeIsInWindow(tripDate, receivedAt)) {
          unclearReason = `trip ${tripId} is outside the seven-day review window`;
          break;
        }
        const linesResult = await pool.query<DbPayoutLine>(
          `SELECT line_id, payout_date::text AS payout_date, rider_id, line_type,
                  trip_id, amount_rupees
           FROM payout_lines WHERE rider_id = $1 AND trip_id = $2 ORDER BY line_id`,
          [canonicalId, tripId],
        );
        const lines = linesResult.rows.map(toPayoutLine);
        events.push({
          type: "tool_call",
          name: "trip_payout_lookup",
          input: { issue_id: issueId, rider_id: canonicalId, trip_id: tripId },
          output: { line_count: lines.length, lines },
        });
        assessments.push(assessTrip(trip, lines));
      }
      if (unclearReason) {
        const suspicious = unclearReason.includes("not linked to this rider account");
        outcomes.push(outcome(issueId, suspicious ? "suspicious" : "unclear", "trip", unclearReason, assessments));
        continue;
      }
      const totalShortfall = assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0);
      const status = resultStatus(totalShortfall);
      outcomes.push(outcome(issueId, status, "trip", "trip records and policy were checked", assessments));
      continue;
    }

    const dates = [...new Set(update.dates)];
    if (dates.length === 0) {
      outcomes.push(outcome(issueId, "needs_information", null, "date"));
      continue;
    }

    const assessments: PayoutAssessment[] = [];
    let unclearReason: string | null = null;
    for (const date of dates) {
      if (!disputeIsInWindow(date, receivedAt)) {
        unclearReason = `${date} is outside the seven-day review window`;
        break;
      }
      const dayTripsResult = await pool.query<DbTrip>(
        `SELECT trip_id, rider_id, started_at, status,
                distance_km::text AS distance_km, surge_multiplier::text AS surge_multiplier
         FROM trips
         WHERE rider_id = $1 AND (started_at AT TIME ZONE 'Asia/Kolkata')::date = $2::date
         ORDER BY started_at, trip_id`,
        [canonicalId, date],
      );
      const trips = dayTripsResult.rows.map(toTrip);
      events.push({
        type: "tool_call",
        name: "day_trip_lookup",
        input: { issue_id: issueId, rider_id: canonicalId, payout_date: date },
        output: { trip_count: trips.length, trip_ids: trips.map((trip) => trip.tripId) },
      });
      if (trips.length === 0) {
        unclearReason = `no trip records were found for ${date}`;
        break;
      }
      const dayLinesResult = await pool.query<DbPayoutLine>(
        `SELECT line_id, payout_date::text AS payout_date, rider_id, line_type,
                trip_id, amount_rupees
         FROM payout_lines WHERE rider_id = $1 AND payout_date = $2::date ORDER BY line_id`,
        [canonicalId, date],
      );
      const lines = dayLinesResult.rows.map(toPayoutLine);
      events.push({
        type: "tool_call",
        name: "day_payout_lookup",
        input: { issue_id: issueId, rider_id: canonicalId, payout_date: date },
        output: { line_count: lines.length, lines },
      });
      assessments.push(assessDay(canonicalId, date, trips, lines));
    }
    if (unclearReason) {
      outcomes.push(outcome(issueId, "unclear", "day", unclearReason, assessments));
      continue;
    }
    const totalShortfall = assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0);
    const status = resultStatus(totalShortfall);
    outcomes.push(outcome(issueId, status, "day", "day records and policy were checked", assessments));
  }

  for (const item of outcomes) {
    events.push({
      type: "decision",
      name: "payout_claim_assessed",
      input: { issue_id: item.issue_id, scope: item.scope },
      output: {
        status: item.status,
        reason: item.reason,
        expected_rupees: item.assessments.reduce((sum, assessment) => sum + assessment.expectedRupees, 0),
        historical_paid_rupees: item.assessments.reduce((sum, assessment) => sum + assessment.historicalPaidRupees, 0),
        shortfall_rupees: item.assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0),
        breakdown: item.assessments.flatMap((assessment) => assessment.breakdown),
      },
    });
  }
  return { outcomes, events };
}

export function appendInvestigationContext(
  state: { issues: Record<string, unknown>[]; [key: string]: unknown },
  outcomes: ClaimOutcome[],
): typeof state {
  if (outcomes.length === 0) return state;
  // Keep monetary evidence in persisted state, outside the issue context sent to Groq.
  return { ...state, latest_investigations: outcomes };
}
import { randomUUID } from "node:crypto";
import { Pool, PoolClient } from "pg";
import {
  appendInvestigationContext,
  InvestigationEvent,
  InvestigationTarget,
  investigateIssues,
} from "./claims.js";
import { decideClaimPaths } from "./decisions.js";
import { executeEligiblePayments, hasUnresolvedPaySwiftPayment, reconcilePaySwiftLedger } from "./payments.js";
import { PaySwiftClient } from "../infrastructure/payswift/client.js";
import {
  GroqMessageUnderstander,
  IssueUpdate,
  LanguageUnderstandingUnavailable,
  MessageUnderstanding,
  RecentMessage,
  sanitizeUnderstanding,
} from "../infrastructure/llm/groq-client.js";

export class MessageIdConflict extends Error {}
export class StoredMessageUnavailable extends Error {}
export class MessageUnderstandingUnavailable extends Error {}

interface StoredInboundMessage {
  rider_id: string;
  text: string;
  received_at: Date;
  reply: string | null;
  processing_status: string;
}

export async function receiveMessage(
  pool: Pool,
  understander: GroqMessageUnderstander,
  args: { messageId: string; riderId: string; text: string; receivedAt: Date },
  paySwift: PaySwiftClient = new PaySwiftClient(),
): Promise<string> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const inserted = await client.query(
      `INSERT INTO inbound_messages (message_id, rider_id, text, received_at, reply, processing_status)
       VALUES ($1, $2, $3, $4, NULL, 'processing')
       ON CONFLICT (message_id) DO NOTHING RETURNING message_id`,
      [args.messageId, args.riderId, args.text, args.receivedAt],
    );

    if (inserted.rowCount === 0) {
      const existing = await client.query<StoredInboundMessage>(
        `SELECT rider_id, text, received_at, reply, processing_status
         FROM inbound_messages WHERE message_id = $1 FOR UPDATE`,
        [args.messageId],
      );
      const stored = existing.rows[0];
      if (!stored) throw new StoredMessageUnavailable("A duplicate message could not be loaded.");
      if (stored.rider_id !== args.riderId || stored.text !== args.text || stored.received_at.getTime() !== args.receivedAt.getTime()) {
        throw new MessageIdConflict("message_id has already been used for different message content.");
      }
      if (stored.processing_status === "processed" && stored.reply !== null) {
        await client.query("COMMIT");
        return stored.reply;
      }
      if (stored.processing_status === "processing") {
        throw new StoredMessageUnavailable("The earlier copy of this message is still being processed.");
      }
      await client.query(
        `UPDATE inbound_messages SET processing_status = 'processing', reply = NULL WHERE message_id = $1`,
        [args.messageId],
      );
    } else {
      await addTrace(client, args.riderId, "message_in", "inbound_message", {
        message_id: args.messageId,
        text: args.text,
        received_at: args.receivedAt.toISOString(),
      }, null);
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  try {
    const { state, recentMessages } = await loadContext(pool, args.riderId, args.messageId);
    let ledgerAvailable = true;
    let ledgerEvents: InvestigationEvent[] = [];
    let reconciliationAttempted = false;
    if (await hasUnresolvedPaySwiftPayment(pool, args.riderId)) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents = reconciliation.events;
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId, reason: "unresolved_payment_follow_up" },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const modelResult = await understander.understand({
      riderId: args.riderId,
      text: args.text,
      receivedAt: args.receivedAt,
      existingIssues: modelIssueContext(state.issues),
      recentMessages,
    });
    const result = sanitizeUnderstanding(modelResult, {
      text: args.text,
      riderId: args.riderId,
      receivedAt: args.receivedAt,
    });
    await addTraceToPool(pool, args.riderId, "model", "groq_message_understanding", {
      message_id: args.messageId,
      active_issue_ids: state.issues.map((issue) => issue.issue_id ?? null),
    }, result);
    const applied = applyUpdates(state, result, args.messageId, args.receivedAt);
    const investigation = await investigateIssues(pool, args.riderId, args.receivedAt, applied.targets);
    await persistEvents(pool, args.riderId, investigation.events);
    const verifiedClaimsExist = investigation.outcomes.some((item) => item.status === "verified_shortfall");
    if (verifiedClaimsExist && !reconciliationAttempted) {
      reconciliationAttempted = true;
      try {
        const reconciliation = await reconcilePaySwiftLedger(pool, args.riderId, paySwift);
        ledgerEvents.push(...reconciliation.events);
      } catch (error) {
        ledgerAvailable = false;
        ledgerEvents = [{
          type: "error",
          name: "payswift_ledger_reconciliation_failed",
          input: { rider_id: args.riderId },
          output: { error: error instanceof Error ? error.message : "unknown PaySwift ledger error", payment_blocked: true },
        }];
      }
      if (ledgerEvents.some((event) => event.type === "error")) await persistEvents(pool, args.riderId, ledgerEvents);
    }
    const decisions = await decideClaimPaths(pool, args.riderId, investigation.outcomes, {
      messageId: args.messageId,
      identityMismatch: result.identity_mismatch,
      paymentProviderAvailable: ledgerAvailable,
    });
    await persistEvents(pool, args.riderId, decisions.events);
    const payments = await executeEligiblePayments(pool, args.riderId, decisions.outcomes, paySwift);
    await persistEvents(pool, args.riderId, payments.events);
    const updatedState = appendInvestigationContext(applied.state, decisions.outcomes);
    const reply = decisions.identityMismatchReply ?? (decisions.outcomes.length > 0
      ? decisions.outcomes.map((item) => item.reply).join(" ")
      : result.reply);
    await saveCompletedMessage(pool, args, reply, updatedState);
    return reply;
  } catch (error) {
    await markFailed(pool, args.messageId, args.riderId,
      error instanceof LanguageUnderstandingUnavailable ? "language_understanding_unavailable" : "message_processing_failed");
    if (error instanceof LanguageUnderstandingUnavailable) {
      throw new MessageUnderstandingUnavailable("Message understanding is temporarily unavailable.", { cause: error });
    }
    throw error;
  }
}

interface ConversationState {
  issues: Record<string, unknown>[];
  [key: string]: unknown;
}

async function loadContext(pool: Pool, riderId: string, currentMessageId: string): Promise<{
  state: ConversationState;
  recentMessages: RecentMessage[];
}> {
  const [conversation, history] = await Promise.all([
    pool.query<{ state: unknown }>("SELECT state FROM conversations WHERE rider_id = $1", [riderId]),
    pool.query<{ received_at: Date; text: string; reply: string | null }>(
      `SELECT received_at, text, reply FROM inbound_messages
       WHERE rider_id = $1 AND message_id <> $2 AND processing_status = 'processed'
       ORDER BY received_at DESC, message_id DESC LIMIT 8`,
      [riderId, currentMessageId],
    ),
  ]);
  const rawState = conversation.rows[0]?.state;
  const stateObject = rawState && typeof rawState === "object" && !Array.isArray(rawState)
    ? rawState as Record<string, unknown> : {};
  const rawIssues = Array.isArray(stateObject.issues) ? stateObject.issues : [];
  return {
    state: { ...stateObject, issues: rawIssues.filter(isJsonObject) },
    recentMessages: history.rows.reverse().map((row) => ({
      received_at: row.received_at.toISOString(),
      rider_message: row.text,
      // Replies may contain deterministic payout amounts; keep them out of Groq context.
      agent_reply: "",
    })),
  };
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function modelIssueContext(issues: Record<string, unknown>[]): Record<string, unknown>[] {
  const allowed = [
    "issue_id", "issue_type", "summary", "trip_ids", "dates",
    "missing_information", "follow_up_question",
  ];
  return issues.map((issue) => Object.fromEntries(
    allowed.filter((key) => key in issue).map((key) => [key, issue[key]]),
  ));
}

function applyUpdates(
  state: ConversationState,
  result: MessageUnderstanding,
  messageId: string,
  receivedAt: Date,
): { state: ConversationState; targets: InvestigationTarget[] } {
  const issues = [...state.issues];
  const targets: InvestigationTarget[] = [];
  if (!result.identity_mismatch) {
    for (const update of result.updates) {
      const issue = issueState(update, receivedAt);
      if (update.action === "create" && update.issue_id === null) {
        const issueId = randomUUID();
        issues.push({ issue_id: issueId, ...issue });
        targets.push({ issueId, update });
      } else if (update.action === "update" && update.issue_id) {
        const index = issues.findIndex((existing) => existing.issue_id === update.issue_id);
        if (index >= 0) {
          issues[index] = { issue_id: update.issue_id, ...issue };
          targets.push({ issueId: update.issue_id, update });
        }
      }
    }
  }
  return {
    state: { ...state, issues, last_message_id: messageId, updated_at: receivedAt.toISOString() },
    targets,
  };
}

function issueState(update: IssueUpdate, receivedAt: Date): Record<string, unknown> {
  return {
    issue_type: update.issue_type,
    summary: update.summary,
    trip_ids: update.trip_ids,
    dates: update.dates,
    missing_information: update.missing_information,
    follow_up_question: update.follow_up_question,
    updated_at: receivedAt.toISOString(),
  };
}

async function saveCompletedMessage(
  pool: Pool,
  args: { messageId: string; riderId: string },
  reply: string,
  updatedState: ConversationState,
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO conversations (rider_id, state) VALUES ($1, $2::jsonb)
       ON CONFLICT (rider_id) DO UPDATE SET state = EXCLUDED.state, updated_at = now()`,
      [args.riderId, JSON.stringify(updatedState)],
    );
    await client.query(
      `UPDATE inbound_messages SET reply = $2, processing_status = 'processed' WHERE message_id = $1`,
      [args.messageId, reply],
    );
    await addTrace(client, args.riderId, "decision", "conversation_context_updated", {
      message_id: args.messageId,
    }, updatedState);
    await addTrace(client, args.riderId, "reply", "rider_follow_up", null, reply);
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

